<template>
  <div class="page"><SiteNav active="reviews"/>
    <main>
      <section class="reviews-hero"><div class="shell"><p class="eyebrow">Client proof / real feedback only</p><h1 class="page-title">The work should speak. <em>Clients can too.</em></h1><p class="intro">Feedback is submitted by real collaborators, held for review, and then displayed here as a permanent public record. No anonymous posts and no invented testimonials.</p></div></section>
      <section class="review-board"><div class="shell"><header class="board-head"><div><p class="eyebrow">Published feedback</p><h2>Verified client notes.</h2></div><p><span class="status-dot"></span>Only approved feedback is shown publicly</p></header><div v-if="loading" class="review-state" role="status">Loading published feedback…</div><div v-else-if="loadError" class="review-state error" role="alert">I couldn’t load the feedback right now. Please try again later.</div><div v-else-if="reviews.length" class="review-grid"><article v-for="review in reviews" :key="review.id"><span class="quote-mark" aria-hidden="true">“</span><blockquote>{{review.message}}</blockquote><footer><strong>{{review.name}}</strong><span>{{review.company}} · {{review.project}}</span></footer></article></div><div v-else class="review-state"><strong>No verified feedback is published yet.</strong><p>Be the first client or collaborator to leave a project note below. It will appear here only after approval.</p></div></div></section>
      <section id="leave-feedback" class="feedback-section"><div class="shell feedback-layout"><div><p class="eyebrow">Leave feedback</p><h2>Worked with me?</h2><p>Share the project, the result, and what collaboration was like. Your message will be recorded as <strong>pending review</strong>; it will not appear on the public wall until I approve it.</p><ul><li>Your words are shown exactly as you submit them.</li><li>Your email and phone are not requested or displayed here.</li><li>Only approved feedback becomes public proof of work.</li></ul></div><form @submit.prevent="submit" novalidate><p class="form-kicker">Client feedback form</p><div v-if="formError" class="form-alert" role="alert">{{formError}}</div><div v-if="state==='success'" class="form-success" aria-live="polite"><strong>Feedback received.</strong> Thank you—your message is pending review before publication.</div><label>Full name <span aria-hidden="true">*</span><input v-model.trim="form.name" required minlength="2" maxlength="60" autocomplete="name" placeholder="Your name"/></label><label>Company or organization <span aria-hidden="true">*</span><input v-model.trim="form.company" required minlength="2" maxlength="80" autocomplete="organization" placeholder="Your company or organization"/></label><label>Project <span aria-hidden="true">*</span><select v-model="form.project" required><option value="" disabled>Select the work you know</option><option>Fingerling Online Ordering Platform</option><option>Ozamiz Schools QR-ID Attendance System</option><option>Tech Savvy platform</option><option>Other project or support work</option></select></label><label>Your feedback <span aria-hidden="true">*</span><textarea v-model.trim="form.message" required minlength="30" maxlength="800" rows="6" placeholder="What did we work on, and what was the result?"></textarea><small>{{form.message.length}} / 800 · minimum 30 characters</small></label><label class="consent"><input v-model="form.consent" type="checkbox" required/><span>I confirm this is my honest feedback and I allow it to be published with my name and organization.</span></label><label class="honeypot" aria-hidden="true">Leave this blank<input v-model="form.website" tabindex="-1" autocomplete="off"/></label><button class="button primary" type="submit" :disabled="state==='submitting' || !reviewsEnabled">{{state==='submitting' ? 'Sending feedback…' : 'Submit for review ↗'}}</button><p v-if="!reviewsEnabled" class="setup-note">The review service is being connected. The public wall is ready; Firebase configuration is the final setup step.</p></form></div></section>
    </main><SiteFooter/>
  </div>
</template>
<script setup>
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { addDoc, collection, onSnapshot, query, serverTimestamp, where } from 'firebase/firestore'
import SiteNav from '../components/SiteNav.vue'
import SiteFooter from '../components/SiteFooter.vue'
import { db, reviewsEnabled } from '../lib/firebase'

const reviews=ref([]), loading=ref(reviewsEnabled), loadError=ref(false), state=ref('idle'), formError=ref('')
const form=reactive({name:'',company:'',project:'',message:'',consent:false,website:''})
let unsubscribe
function sortReviews(items){return items.sort((a,b)=>(b.createdAt?.toMillis?.()||0)-(a.createdAt?.toMillis?.()||0))}
onMounted(()=>{if(!reviewsEnabled)return;unsubscribe=onSnapshot(query(collection(db,'testimonials'),where('status','==','approved')),(snapshot)=>{reviews.value=sortReviews(snapshot.docs.map((doc)=>({id:doc.id,...doc.data()})));loading.value=false},()=>{loadError.value=true;loading.value=false})})
onUnmounted(()=>unsubscribe?.())
function valid(){if(form.website)return 'Your submission could not be accepted.';if(form.name.length<2||form.name.length>60)return 'Enter your full name (2–60 characters).';if(form.company.length<2||form.company.length>80)return 'Enter your company or organization (2–80 characters).';if(!form.project)return 'Choose the project or work you know.';if(form.message.length<30||form.message.length>800)return 'Feedback must be between 30 and 800 characters.';if(!form.consent)return 'Please confirm that you allow this feedback to be published.';return ''}
async function submit(){formError.value='';const error=valid();if(error){formError.value=error;return}if(!reviewsEnabled){formError.value='The review service is not configured yet. Please try again soon.';return}state.value='submitting';try{await addDoc(collection(db,'testimonials'),{name:form.name,company:form.company,project:form.project,message:form.message,status:'pending',consent:true,createdAt:serverTimestamp()});Object.assign(form,{name:'',company:'',project:'',message:'',consent:false,website:''});state.value='success'}catch{formError.value='Your feedback could not be saved. Please try again later.';state.value='idle'}}
</script>
<style scoped>
.reviews-hero{padding:105px 0 84px;border-bottom:1px solid var(--line);background:radial-gradient(circle at 82% 25%,rgba(184,255,75,.10),transparent 23rem)}.review-board{padding:91px 0 100px}.board-head{display:flex;justify-content:space-between;align-items:end;gap:35px;margin-bottom:35px}.board-head h2{font-size:clamp(2.4rem,4.7vw,4.7rem);line-height:.95;letter-spacing:-.075em;margin:18px 0 0}.board-head>p{margin:0;color:var(--muted);font:.72rem var(--mono);letter-spacing:.05em}.status-dot{display:inline-block;width:7px;height:7px;background:var(--lime);box-shadow:0 0 9px var(--lime);margin-right:6px}.review-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.review-grid article{min-height:300px;padding:25px;border:1px solid var(--line);background:linear-gradient(145deg,rgba(18,25,38,.77),rgba(13,17,24,.8));display:flex;flex-direction:column}.quote-mark{font:700 4rem/.65 Georgia,serif;color:var(--lime)}blockquote{margin:25px 0;font-size:1.04rem;line-height:1.6;color:#e8eef5}footer{margin-top:auto;border-top:1px solid var(--line);padding-top:14px}footer strong,footer span{display:block}footer strong{font-size:.82rem}footer span{color:var(--muted);font-size:.72rem;margin-top:3px}.review-state{border:1px dashed var(--line-strong);padding:36px;max-width:700px;color:var(--muted)}.review-state strong{color:var(--text);display:block;margin-bottom:5px}.review-state p{margin:0}.review-state.error{border-color:rgba(255,109,141,.5);color:#ffc1d0}.feedback-section{border-top:1px solid var(--line);padding:98px 0;background:rgba(82,231,255,.035)}.feedback-layout{display:grid;grid-template-columns:.82fr 1.18fr;gap:100px}.feedback-layout h2{font-size:clamp(2.7rem,5vw,5rem);line-height:.91;letter-spacing:-.08em;margin:18px 0}.feedback-layout>div>p:not(.eyebrow){color:var(--muted);max-width:470px}.feedback-layout ul{list-style:none;padding:0;margin:28px 0 0}.feedback-layout li{padding:9px 0 9px 17px;position:relative;color:#d5deea;font-size:.84rem}.feedback-layout li:before{content:'+';position:absolute;left:0;color:var(--lime);font-weight:800}form{padding:29px;border:1px solid var(--line);background:var(--panel);display:grid;gap:17px}.form-kicker{font:600 1.2rem var(--font);letter-spacing:-.035em;margin:0 0 3px}label{font-size:.76rem;font-weight:800;color:#e6edf4}label>span{color:var(--lime)}input,select,textarea{display:block;width:100%;margin-top:7px;padding:12px;border:1px solid var(--line);background:#080c12;color:var(--text);font:400 .91rem var(--font);border-radius:0}input:focus,select:focus,textarea:focus{outline:2px solid rgba(82,231,255,.55);outline-offset:1px;border-color:var(--cyan)}textarea{resize:vertical;min-height:140px}label small{display:block;margin-top:6px;color:var(--muted);font:400 .64rem var(--mono)}.consent{display:flex;align-items:flex-start;gap:10px;color:var(--muted);font-size:.76rem;line-height:1.5}.consent input{width:18px;height:18px;margin:1px 0 0;flex:none;accent-color:var(--lime)}.honeypot{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}.form-alert,.form-success,.setup-note{margin:0;padding:10px 12px;font-size:.76rem;line-height:1.5}.form-alert{border:1px solid rgba(255,109,141,.5);color:#ffd0da;background:rgba(255,109,141,.06)}.form-success{border:1px solid rgba(184,255,75,.45);color:#e1ffc0;background:rgba(184,255,75,.06)}.setup-note{color:var(--orange);padding:0}.button:disabled{opacity:.55;cursor:not-allowed;transform:none}@media(max-width:800px){.reviews-hero{padding:76px 0 64px}.board-head{display:block}.board-head>p{margin-top:15px}.review-grid{grid-template-columns:1fr}.feedback-layout{grid-template-columns:1fr;gap:43px}}@media(max-width:520px){form{padding:20px}.review-grid article{min-height:250px}}
</style>
